<script setup lang="ts">import{Head,Link,router}from'@inertiajs/vue3';import{ref}from'vue';import AuthenticatedLayout from'../../Layouts/AuthenticatedLayout.vue';type Row={id:number;warehouse:{slug:string;name:string};product:{id:number;sku:string;name:string};inbound_at:string|null;stay_days:number|null;location:string|null;quantity_on_hand:number;quantity_reserved:number;quantity_available:number;standard_qoh:number|null;expected_restock_qty:number};type W={slug:string;name:string};const props=defineProps<{rows:{data:Row[];links:any[];current_page:number;last_page:number};warehouses:W[];filters:{search?:string;warehouse?:string}}>();const search=ref(props.filters.search||'');const warehouse=ref(props.filters.warehouse||'');const apply=()=>router.get('/inventory/products',{search:search.value,warehouse:warehouse.value},{preserveState:true,replace:true});const breadcrumbs=[{label:'BYL ERP',href:'/dashboard'},{label:'库存',href:'/inventory'},'产品库存']</script>
<template><Head title="产品库存 · BYL ERP"/><AuthenticatedLayout title="产品库存" :breadcrumbs="breadcrumbs"><section class="mvp-page"><div class="mvp-page-heading"><div><p class="mvp-kicker">Product × Warehouse</p><h2>产品对应仓库清单</h2><p>统一统计产品在各仓库的库存、上架时间与停留时间。</p></div><Link class="mvp-button" href="/inventory/list">仓库清单</Link></div><div class="mvp-card filters"><input v-model="search" placeholder="搜索 SKU / 产品名称" @keyup.enter="apply"><select v-model="warehouse" @change="apply"><option value="">全部仓库</option><option v-for="w in warehouses" :key="w.slug" :value="w.slug">{{w.name}}</option></select><button class="mvp-button" @click="apply">筛选</button></div><div class="mvp-card table-wrap"><table><thead><tr><th>所属仓库</th><th>SKU</th><th>产品</th><th>上架时间</th><th>停留时间</th><th>Location</th><th>当前库存</th><th>预留</th><th>可用库存</th><th>Standard QoH</th><th>预计备货</th></tr></thead><tbody><tr v-for="r in rows.data" :key="r.id"><td><Link :href="`/inventory/${r.warehouse.slug}`">{{r.warehouse.name}}</Link></td><td><strong>{{r.product.sku||'—'}}</strong></td><td>{{r.product.name}}</td><td>{{r.inbound_at||'—'}}</td><td>{{r.stay_days===null?'—':`${r.stay_days} 天`}}</td><td>{{r.location||'—'}}</td><td>{{r.quantity_on_hand}}</td><td>{{r.quantity_reserved}}</td><td><strong>{{r.quantity_available}}</strong></td><td>{{r.standard_qoh??'—'}}</td><td>{{r.expected_restock_qty}}</td></tr><tr v-if="!rows.data.length"><td colspan="11">暂无库存数据</td></tr></tbody></table></div></section></AuthenticatedLayout></template>
<style scoped>.filters{display:flex;gap:10px}.filters input,.filters select{padding:9px;border:1px solid #dbe2e8;border-radius:8px}.filters input{min-width:280px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #e5e7eb;text-align:left;white-space:nowrap}th{font-size:12px;color:#64748b}</style>
